227	        {
228	          headers: { apikey: anonKey },
229	        }
230	      );
231	
232	      const json = await res.json();
233	
234	      if (!res.ok) {
235	        const msg = (json.error as string) ?? "Failed to load";
236	        const type: PortalError["type"] =
237	          msg.toLowerCase().includes("revoked")
238	            ? "revoked"
239	            : msg.toLowerCase().includes("expired")
240	            ? "expired"
241	            : msg.toLowerCase().includes("not found")
242	            ? "not_found"
243	            : "unknown";
244	        throw { type, message: msg } as PortalError;
245	      }
246	
247	      return json as PortalData;
248	    },
249	    enabled: !!token,
250	    retry: false,
251	    staleTime: 60_000,
