import { useEffect } from "react";
import { useQuery, useMutation, useQueryClient } from "@tanstack/react-query";
import { supabase } from "@/integrations/supabase/client";
import { toast } from "sonner";

// ─── Types ────────────────────────────────────────────────────────────────────

export interface PipelineStage {
  id: string;
  team_id: string;
  name: string;
  color: string;
  sort_order: number;
  is_default: boolean;
  created_at: string;
}

export interface PipelineStageWithRejected extends PipelineStage {
  synthetic?: boolean;
}

// Default stages used as fallback when no team or no custom stages configured
export const DEFAULT_STAGES: PipelineStage[] = [
  { id: "default-applied",   team_id: "", name: "Applied",   color: "#6b7280", sort_order: 0, is_default: true, created_at: "" },
  { id: "default-screened",  team_id: "", name: "Screened",  color: "#3b82f6", sort_order: 1, is_default: true, created_at: "" },
  { id: "default-interview", team_id: "", name: "Interview", color: "#8b5cf6", sort_order: 2, is_default: true, created_at: "" },
  { id: "default-offer",     team_id: "", name: "Offer",     color: "#f59e0b", sort_order: 3, is_default: true, created_at: "" },
  { id: "default-hired",     team_id: "", name: "Hired",     color: "#10b981", sort_order: 4, is_default: true, created_at: "" },
];

const REJECTED_STAGE: PipelineStageWithRejected = {
  id: "synthetic-rejected",
  team_id: "",
  name: "Rejected",
  color: "#ef4444",
  sort_order: 999,
  is_default: false,
  created_at: "",
  synthetic: true,
};

// ─── Fetch ───────────────────────────────────────────────────────────────────

async function fetchStages(teamId: string): Promise<PipelineStage[]> {
  try {
    const { data, error } = await (supabase as any)
      .from("pipeline_stages")
      .select("*")
      .eq("team_id", teamId)
      .order("sort_order", { ascending: true });

    if (error) {
      if (
        error.message?.includes("schema cache") ||
        error.message?.includes("does not exist") ||
        error.code === "42P01"
      ) {
        return [];
      }
      throw error;
    }
    return (data ?? []) as PipelineStage[];
  } catch (err: unknown) {
    const e = err as { message?: string };
    if (e?.message?.includes("schema cache") || e?.message?.includes("does not exist")) {
      return [];
    }
    throw err;
  }
}

// ─── usePipelineStages ───────────────────────────────────────────────────────

export function usePipelineStages(teamId: string | null | undefined) {
  const queryClient = useQueryClient();

  const query = useQuery({
    queryKey: ["pipeline-stages", teamId],
    queryFn: () => fetchStages(teamId!),
    enabled: !!teamId,
    staleTime: 60_000,
    retry: false,
  });

  // Realtime subscription — keeps stages in sync when another admin edits
  useEffect(() => {
    if (!teamId) return;

    const channel = supabase
      .channel(`pipeline-stages-${teamId}`)
      .on(
        "postgres_changes",
        { event: "*", schema: "public", table: "pipeline_stages", filter: `team_id=eq.${teamId}` },
        () => {
          queryClient.invalidateQueries({ queryKey: ["pipeline-stages", teamId] });
        }
      )
      .subscribe();

    return () => {
      supabase.removeChannel(channel);
    };
  }, [teamId, queryClient]);

  const rawStages: PipelineStage[] =
    query.data && query.data.length > 0 ? query.data : (teamId ? [] : DEFAULT_STAGES);

  // Always fall back to DEFAULT_STAGES if loaded but empty
  const baseStages: PipelineStage[] =
    !teamId ? DEFAULT_STAGES : query.data && query.data.length > 0 ? query.data : DEFAULT_STAGES;

  // Append synthetic Rejected entry
  const stagesWithRejected: PipelineStageWithRejected[] = [...baseStages, REJECTED_STAGE];

  return {
    ...query,
    stages: baseStages,
    stagesWithRejected,
    rawStages,
  };
}

// ─── CRUD Mutations ───────────────────────────────────────────────────────────

export function useCreatePipelineStage(teamId: string) {
  const queryClient = useQueryClient();

  return useMutation({
    mutationFn: async (input: { name: string; color: string }) => {
      // Determine next sort_order
      const existing = queryClient.getQueryData<PipelineStage[]>(["pipeline-stages", teamId]) ?? [];
      const maxOrder = existing.reduce((m, s) => Math.max(m, s.sort_order), -1);

      const { data, error } = await (supabase as any)
        .from("pipeline_stages")
        .insert({ team_id: teamId, name: input.name, color: input.color, sort_order: maxOrder + 1 })
        .select()
        .single();

      if (error) throw error;
      return data as PipelineStage;
    },
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey: ["pipeline-stages", teamId] });
      toast.success("Stage created");
    },
    onError: (err: Error) => {
      toast.error(err.message ?? "Failed to create stage");
    },
  });
}

export function useUpdatePipelineStage(teamId: string) {
  const queryClient = useQueryClient();

  return useMutation({
    mutationFn: async (input: { id: string; name?: string; color?: string }) => {
      const { id, ...rest } = input;
      const { error } = await (supabase as any)
        .from("pipeline_stages")
        .update(rest)
        .eq("id", id);
      if (error) throw error;
    },
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey: ["pipeline-stages", teamId] });
      toast.success("Stage updated");
    },
    onError: (err: Error) => {
      toast.error(err.message ?? "Failed to update stage");
    },
  });
}

export function useDeletePipelineStage(teamId: string) {
  const queryClient = useQueryClient();

  return useMutation({
    mutationFn: async (id: string) => {
      const { error } = await (supabase as any)
        .from("pipeline_stages")
        .delete()
        .eq("id", id);
      if (error) throw error;
    },
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey: ["pipeline-stages", teamId] });
      toast.success("Stage deleted");
    },
    onError: (err: Error) => {
      toast.error(err.message ?? "Failed to delete stage");
    },
  });
}

export function useReorderPipelineStages(teamId: string) {
  const queryClient = useQueryClient();

  return useMutation({
    mutationFn: async (ordered: PipelineStage[]) => {
      // Batch update sort_order via individual upserts
      const updates = ordered.map((s, i) =>
        (supabase as any)
          .from("pipeline_stages")
          .update({ sort_order: i })
          .eq("id", s.id)
      );
      await Promise.all(updates);
    },
    onMutate: async (ordered) => {
      await queryClient.cancelQueries({ queryKey: ["pipeline-stages", teamId] });
      const previous = queryClient.getQueryData<PipelineStage[]>(["pipeline-stages", teamId]);
      queryClient.setQueryData<PipelineStage[]>(
        ["pipeline-stages", teamId],
        ordered.map((s, i) => ({ ...s, sort_order: i }))
      );
      return { previous };
    },
    onError: (_err, _vars, context) => {
      if (context?.previous) {
        queryClient.setQueryData(["pipeline-stages", teamId], context.previous);
      }
      toast.error("Failed to reorder stages");
    },
    onSettled: () => {
      queryClient.invalidateQueries({ queryKey: ["pipeline-stages", teamId] });
    },
  });
}

