import { useQuery, useMutation, useQueryClient } from "@tanstack/react-query";
import { supabase } from "@/integrations/supabase/client";
import { useAuth } from "@/hooks/useAuth";
import { toast } from "sonner";

// ─── Types ────────────────────────────────────────────────────────────────────

export type Recommendation = "strong_yes" | "yes" | "neutral" | "no" | "strong_no";

export interface ScorecardResponse {
  id: string;
  template_id: string;
  resume_id: string;
  job_id: string;
  evaluator_id: string;
  scores: Record<string, number>;
  overall_comment: string | null;
  recommendation: Recommendation;
  created_at: string;
  updated_at: string;
}

// ─── Fetch ───────────────────────────────────────────────────────────────────

async function fetchResponses(resumeId: string, jobId: string): Promise<ScorecardResponse[]> {
  try {
    const { data, error } = await (supabase as any)
      .from("scorecard_responses")
      .select("*")
      .eq("resume_id", resumeId)
      .eq("job_id", jobId)
      .order("created_at", { ascending: false });

    if (error) {
      if (
        error.message?.includes("schema cache") ||
        error.message?.includes("does not exist") ||
        error.code === "42P01"
      ) {
        return [];
      }
      throw error;
    }
    return (data ?? []) as ScorecardResponse[];
  } catch (err: unknown) {
    const e = err as { message?: string };
    if (e?.message?.includes("schema cache") || e?.message?.includes("does not exist")) {
      return [];
    }
    throw err;
  }
}

// ─── useScorecardResponses ────────────────────────────────────────────────────

export function useScorecardResponses(
  resumeId: string | null | undefined,
  jobId: string | null | undefined
) {
  return useQuery({
    queryKey: ["scorecard-responses", resumeId, jobId],
    queryFn: () => fetchResponses(resumeId!, jobId!),
    enabled: !!resumeId && !!jobId,
    staleTime: 30_000,
    retry: false,
  });
}

// ─── Upsert Mutation ─────────────────────────────────────────────────────────

export function useSubmitScorecardResponse() {
  const queryClient = useQueryClient();
  const { user } = useAuth();

  return useMutation({
    mutationFn: async (input: {
      templateId: string;
      resumeId: string;
      jobId: string;
      scores: Record<string, number>;
      overallComment?: string;
      recommendation: Recommendation;
    }) => {
      if (!user?.id) throw new Error("Not authenticated");

      const payload = {
        template_id: input.templateId,
        resume_id: input.resumeId,
        job_id: input.jobId,
        evaluator_id: user.id,
        scores: input.scores,
        overall_comment: input.overallComment ?? null,
        recommendation: input.recommendation,
        updated_at: new Date().toISOString(),
      };

      const { data, error } = await (supabase as any)
        .from("scorecard_responses")
        .upsert(payload, { onConflict: "template_id,resume_id,evaluator_id" })
        .select()
        .single();

      if (error) throw error;
      return data as ScorecardResponse;
    },
    onSuccess: (_data, variables) => {
      queryClient.invalidateQueries({
        queryKey: ["scorecard-responses", variables.resumeId, variables.jobId],
      });
      toast.success("Evaluation submitted");
    },
    onError: (err: Error) => {
      toast.error(err.message ?? "Failed to submit evaluation");
    },
  });
}

