// ─── Color palette ────────────────────────────────────────────────────────────

const PRESET_COLORS = [
  "#6b7280", // gray
  "#3b82f6", // blue
  "#8b5cf6", // violet
  "#f59e0b", // amber
  "#10b981", // emerald
