// ─── ColorPicker ─────────────────────────────────────────────────────────────

function ColorPicker({ value, onChange }: { value: string; onChange: (color: string) => void }) {
  return (
    <div className="flex flex-wrap gap-1.5">
      {PRESET_COLORS.map((color) => (
        <button
          key={color}
          type="button"
          onClick={() => onChange(color)}
          className={`w-5 h-5 rounded-full border-2 transition-transform hover:scale-110 ${
            value === color ? "border-foreground scale-110" : "border-transparent"
          }`}
          style={{ backgroundColor: color }}
          aria-label={`Select color ${color}`}
        />
      ))}
    </div>
  );
}

// ─── AddStageRow ─────────────────────────────────────────────────────────────

function AddStageRow({
  teamId,
  onDone,
}: {
  teamId: string;
  onDone: () => void;
}) {
  const [name, setName] = useState("");
  const [color, setColor] = useState(PRESET_COLORS[0]);
  const createMutation = useCreatePipelineStage(teamId);

  async function handleCreate() {
    if (!name.trim()) {
      toast.error("Stage name is required");
      return;
    }
    await createMutation.mutateAsync({ name: name.trim(), color });
    onDone();
  }

  return (
    <div className="border border-dashed border-border rounded-lg p-3 space-y-2 bg-muted/20">
      <div className="flex items-center gap-2">
        <div className="w-4 h-4 rounded-full shrink-0" style={{ backgroundColor: color }} />
        <Input
          autoFocus
          placeholder="Stage name…"
          value={name}
          onChange={(e) => setName(e.target.value)}
          className="h-7 text-sm flex-1"
          onKeyDown={(e) => {
            if (e.key === "Enter") handleCreate();
            if (e.key === "Escape") onDone();
          }}
          maxLength={50}
        />
      </div>
      <ColorPicker value={color} onChange={setColor} />
      <div className="flex items-center gap-2 justify-end">
        <Button variant="ghost" size="sm" className="h-7 text-xs" onClick={onDone}>
          Cancel
        </Button>
        <Button
          size="sm"
          className="h-7 text-xs"
          onClick={handleCreate}
          disabled={createMutation.isPending || !name.trim()}
        >
          {createMutation.isPending ? <Loader2 className="h-3.5 w-3.5 animate-spin mr-1" /> : <Plus className="h-3.5 w-3.5 mr-1" />}
          Add
        </Button>
      </div>
    </div>
  );
}

// ─── StageRow ────────────────────────────────────────────────────────────────

function StageRow({
  stage,
  teamId,
  canMoveUp,
  canMoveDown,
  onMoveUp,
  onMoveDown,
  canDelete,
}: {
  stage: PipelineStage;
  teamId: string;
  canMoveUp: boolean;
  canMoveDown: boolean;
  onMoveUp: () => void;
  onMoveDown: () => void;
  canDelete: boolean;
}) {
  const [editing, setEditing] = useState(false);
  const [editName, setEditName] = useState(stage.name);
  const [editColor, setEditColor] = useState(stage.color);
  const updateMutation = useUpdatePipelineStage(teamId);
  const deleteMutation = useDeletePipelineStage(teamId);

  function startEdit() {
    setEditName(stage.name);
    setEditColor(stage.color);
    setEditing(true);
  }

  async function saveEdit() {
    if (!editName.trim()) {
      toast.error("Stage name is required");
      return;
    }
    await updateMutation.mutateAsync({ id: stage.id, name: editName.trim(), color: editColor });
    setEditing(false);
  }

  function cancelEdit() {
    setEditing(false);
  }

  if (editing) {
    return (
      <div className="border border-primary/30 rounded-lg p-3 space-y-2 bg-muted/20">
        <div className="flex items-center gap-2">
          <div className="w-4 h-4 rounded-full shrink-0" style={{ backgroundColor: editColor }} />
          <Input
            autoFocus
            value={editName}
            onChange={(e) => setEditName(e.target.value)}
            className="h-7 text-sm flex-1"
            onKeyDown={(e) => {
              if (e.key === "Enter") saveEdit();
              if (e.key === "Escape") cancelEdit();
            }}
            maxLength={50}
          />
        </div>
        <ColorPicker value={editColor} onChange={setEditColor} />
        <div className="flex items-center gap-2 justify-end">
          <Button variant="ghost" size="sm" className="h-7 w-7 p-0" onClick={cancelEdit}>
            <X className="h-3.5 w-3.5" />
          </Button>
          <Button
            size="sm"
            className="h-7 gap-1 text-xs"
            onClick={saveEdit}
            disabled={updateMutation.isPending}
          >
            {updateMutation.isPending ? <Loader2 className="h-3.5 w-3.5 animate-spin" /> : <Check className="h-3.5 w-3.5" />}
            Save
          </Button>
        </div>
      </div>
    );
  }

  return (
    <div className="flex items-center gap-2 px-2 py-1.5 rounded-lg hover:bg-muted/40 transition-colors group">
      <GripVertical className="h-4 w-4 text-muted-foreground/30 group-hover:text-muted-foreground/60 shrink-0" />
      <div className="w-3 h-3 rounded-full shrink-0" style={{ backgroundColor: stage.color }} />
      <span className="flex-1 text-sm font-medium truncate">{stage.name}</span>
      {stage.is_default && (
        <Badge variant="outline" className="text-[10px] py-0 h-4 shrink-0">Default</Badge>
      )}

      {/* Reorder buttons */}
      <div className="flex flex-col shrink-0 opacity-0 group-hover:opacity-100 transition-opacity">
        <button
          className="h-4 w-4 flex items-center justify-center text-muted-foreground hover:text-foreground disabled:opacity-30"
          disabled={!canMoveUp}
          onClick={onMoveUp}
          aria-label="Move up"
        >
          <ChevronUp className="h-3 w-3" />
        </button>
        <button
          className="h-4 w-4 flex items-center justify-center text-muted-foreground hover:text-foreground disabled:opacity-30"
          disabled={!canMoveDown}
          onClick={onMoveDown}
          aria-label="Move down"
        >
          <ChevronDown className="h-3 w-3" />
        </button>
      </div>

      {/* Edit */}
      <Button
        variant="ghost"
        size="icon"
        className="h-6 w-6 opacity-0 group-hover:opacity-100 transition-opacity shrink-0"
        onClick={startEdit}
        aria-label="Edit stage"
      >
        <Pencil className="h-3 w-3" />
      </Button>

      {/* Delete */}
      <AlertDialog>
        <AlertDialogTrigger asChild>
          <Button
            variant="ghost"
            size="icon"
            className="h-6 w-6 opacity-0 group-hover:opacity-100 transition-opacity text-muted-foreground hover:text-destructive shrink-0"
            disabled={!canDelete || deleteMutation.isPending}
            aria-label="Delete stage"
          >
            {deleteMutation.isPending ? (
              <Loader2 className="h-3 w-3 animate-spin" />
            ) : (
              <Trash2 className="h-3 w-3" />
            )}
          </Button>
        </AlertDialogTrigger>
        <AlertDialogContent>
          <AlertDialogHeader>
            <AlertDialogTitle>Delete "{stage.name}"?</AlertDialogTitle>
            <AlertDialogDescription>
              This stage will be removed from your pipeline. Candidates in this stage will remain but may appear under their last assigned stage.
            </AlertDialogDescription>
          </AlertDialogHeader>
          <AlertDialogFooter>
            <AlertDialogCancel>Cancel</AlertDialogCancel>
            <AlertDialogAction
              className="bg-destructive text-destructive-foreground hover:bg-destructive/90"
              onClick={() => deleteMutation.mutate(stage.id)}
            >
              Delete
            </AlertDialogAction>
          </AlertDialogFooter>
        </AlertDialogContent>
      </AlertDialog>
    </div>
  );
}

// ─── PipelineStageManager ─────────────────────────────────────────────────────

interface PipelineStageManagerProps {
  teamId: string;
}

export default function PipelineStageManager({ teamId }: PipelineStageManagerProps) {
  const [showAdd, setShowAdd] = useState(false);
  const { stages, isLoading } = usePipelineStages(teamId);
  const reorderMutation = useReorderPipelineStages(teamId);

  function moveStage(index: number, direction: "up" | "down") {
    const newOrder = [...stages];
    const swapIndex = direction === "up" ? index - 1 : index + 1;
    if (swapIndex < 0 || swapIndex >= newOrder.length) return;
    [newOrder[index], newOrder[swapIndex]] = [newOrder[swapIndex], newOrder[index]];
    reorderMutation.mutate(newOrder);
  }

  const nonRejectedStages = stages.filter((s) => s.name.toLowerCase() !== "rejected");
  const canDelete = nonRejectedStages.length > 2;

  return (
    <Card className="border border-border/60 shadow-sm">
      <CardHeader className="pb-3">
        <div className="flex items-center justify-between">
          <CardTitle className="text-sm font-semibold">Pipeline Stages</CardTitle>
          <Button
            variant="outline"
            size="sm"
            className="h-7 gap-1 text-xs"
            onClick={() => setShowAdd(true)}
            disabled={showAdd}
          >
            <Plus className="h-3.5 w-3.5" />
            Add Stage
          </Button>
        </div>
        <p className="text-xs text-muted-foreground">
          Customize the hiring stages for this team. "Rejected" is always available as a final state.
        </p>
      </CardHeader>
      <CardContent className="space-y-1">
        {isLoading ? (
          <div className="space-y-2">
            {[1, 2, 3, 4, 5].map((i) => (
              <Skeleton key={i} className="h-8 w-full" />
            ))}
          </div>
        ) : (
          <>
            {nonRejectedStages.map((stage, i) => (
              <StageRow
                key={stage.id}
                stage={stage}
                teamId={teamId}
                canMoveUp={i > 0}
                canMoveDown={i < nonRejectedStages.length - 1}
                onMoveUp={() => moveStage(i, "up")}
                onMoveDown={() => moveStage(i, "down")}
                canDelete={canDelete}
              />
            ))}

            {/* Rejected — always last, cannot be deleted */}
            <div className="flex items-center gap-2 px-2 py-1.5 rounded-lg opacity-60 cursor-not-allowed">
              <GripVertical className="h-4 w-4 text-muted-foreground/20 shrink-0" />
              <div className="w-3 h-3 rounded-full shrink-0 bg-red-500" />
              <span className="flex-1 text-sm font-medium text-muted-foreground">Rejected</span>
              <Badge variant="outline" className="text-[10px] py-0 h-4">Always last</Badge>
            </div>

            {showAdd && (
              <div className="mt-2">
                <AddStageRow teamId={teamId} onDone={() => setShowAdd(false)} />
              </div>
            )}

            {nonRejectedStages.length === 0 && !showAdd && (
              <p className="text-xs text-muted-foreground text-center py-4">
                No custom stages yet. Click "Add Stage" to create your pipeline.
              </p>
            )}
          </>
        )}
      </CardContent>
    </Card>
  );
}

