// ─── CriterionEditor ─────────────────────────────────────────────────────────

interface CriterionEditorProps {
  criteria: ScorecardCriterion[];
  onChange: (criteria: ScorecardCriterion[]) => void;
}

function CriterionEditor({ criteria, onChange }: CriterionEditorProps) {
  function addCriterion() {
    const newCriterion: ScorecardCriterion = {
      id: crypto.randomUUID(),
      label: "",
      description: "",
      max_score: 5,
    };
    onChange([...criteria, newCriterion]);
  }

  function updateCriterion(id: string, patch: Partial<ScorecardCriterion>) {
    onChange(criteria.map((c) => (c.id === id ? { ...c, ...patch } : c)));
  }

  function removeCriterion(id: string) {
    onChange(criteria.filter((c) => c.id !== id));
  }

  function moveCriterion(index: number, direction: "up" | "down") {
    const next = [...criteria];
    const swapIndex = direction === "up" ? index - 1 : index + 1;
    if (swapIndex < 0 || swapIndex >= next.length) return;
    [next[index], next[swapIndex]] = [next[swapIndex], next[index]];
    onChange(next);
  }

  return (
    <div className="space-y-2">
      {criteria.map((c, i) => (
        <div key={c.id} className="border border-border rounded-lg p-3 space-y-2 bg-muted/20 group">
          <div className="flex items-start gap-2">
            <GripVertical className="h-4 w-4 text-muted-foreground/30 shrink-0 mt-1" />
            <div className="flex-1 space-y-2">
              <div className="flex items-center gap-2">
                <Input
                  placeholder="Criterion label (e.g. Communication)"
                  value={c.label}
                  onChange={(e) => updateCriterion(c.id, { label: e.target.value })}
                  className="h-7 text-sm flex-1"
                  maxLength={80}
                />
                <div className="flex items-center gap-1 shrink-0">
                  <Label className="text-xs text-muted-foreground whitespace-nowrap">Max</Label>
                  <Input
                    type="number"
                    min={1}
                    max={10}
                    value={c.max_score}
                    onChange={(e) =>
                      updateCriterion(c.id, { max_score: Math.min(10, Math.max(1, Number(e.target.value))) })
                    }
                    className="h-7 w-14 text-sm text-center"
                  />
                </div>
              </div>
              <Textarea
                placeholder="Optional description…"
                value={c.description ?? ""}
                onChange={(e) => updateCriterion(c.id, { description: e.target.value })}
                className="text-xs min-h-[48px] resize-none"
                maxLength={200}
              />
            </div>
            <div className="flex flex-col gap-0.5 shrink-0">
              <button
                type="button"
                className="h-5 w-5 flex items-center justify-center text-muted-foreground hover:text-foreground disabled:opacity-30"
                disabled={i === 0}
                onClick={() => moveCriterion(i, "up")}
              >
                <ChevronUp className="h-3.5 w-3.5" />
              </button>
              <button
                type="button"
                className="h-5 w-5 flex items-center justify-center text-muted-foreground hover:text-foreground disabled:opacity-30"
                disabled={i === criteria.length - 1}
                onClick={() => moveCriterion(i, "down")}
              >
                <ChevronDown className="h-3.5 w-3.5" />
              </button>
              <button
                type="button"
                className="h-5 w-5 flex items-center justify-center text-muted-foreground hover:text-destructive"
                onClick={() => removeCriterion(c.id)}
              >
                <X className="h-3.5 w-3.5" />
              </button>
            </div>
          </div>
        </div>
      ))}
      <Button
        type="button"
        variant="outline"
        size="sm"
        className="h-7 gap-1 text-xs w-full"
        onClick={addCriterion}
      >
        <Plus className="h-3.5 w-3.5" />
        Add Criterion
      </Button>
    </div>
  );
}

// ─── TemplateForm ─────────────────────────────────────────────────────────────

interface TemplateFormProps {
  teamId: string;
  initial?: ScorecardTemplate;
  onClose: () => void;
}

function TemplateForm({ teamId, initial, onClose }: TemplateFormProps) {
  const [name, setName] = useState(initial?.name ?? "");
  const [criteria, setCriteria] = useState<ScorecardCriterion[]>(
    initial?.criteria ?? [
      { id: crypto.randomUUID(), label: "Communication", description: "Clarity and articulation", max_score: 5 },
      { id: crypto.randomUUID(), label: "Technical Skills", description: "Relevant technical proficiency", max_score: 5 },
    ]
  );

  const createMutation = useCreateScorecardTemplate(teamId);
  const updateMutation = useUpdateScorecardTemplate(teamId);
  const isPending = createMutation.isPending || updateMutation.isPending;

  async function handleSubmit() {
    if (!name.trim()) {
      toast.error("Template name is required");
      return;
    }
    const validCriteria = criteria.filter((c) => c.label.trim());
    if (validCriteria.length === 0) {
      toast.error("Add at least one criterion");
      return;
    }

    if (initial) {
      await updateMutation.mutateAsync({ id: initial.id, name: name.trim(), criteria: validCriteria });
    } else {
      await createMutation.mutateAsync({ name: name.trim(), criteria: validCriteria });
    }
    onClose();
  }

  return (
    <div className="border border-primary/20 rounded-lg p-4 space-y-3 bg-muted/10">
      <div className="space-y-1">
        <Label className="text-xs font-medium">Template Name</Label>
        <Input
          autoFocus
          placeholder="e.g. Standard Technical Interview"
          value={name}
          onChange={(e) => setName(e.target.value)}
          className="h-8 text-sm"
          maxLength={100}
        />
      </div>
      <div className="space-y-1">
        <Label className="text-xs font-medium">Evaluation Criteria</Label>
        <CriterionEditor criteria={criteria} onChange={setCriteria} />
      </div>
      <div className="flex items-center gap-2 justify-end pt-1">
        <Button variant="ghost" size="sm" className="h-7 text-xs" onClick={onClose}>
          Cancel
        </Button>
        <Button
          size="sm"
          className="h-7 gap-1 text-xs"
          onClick={handleSubmit}
          disabled={isPending}
        >
          {isPending ? (
            <Loader2 className="h-3.5 w-3.5 animate-spin" />
          ) : (
            <Check className="h-3.5 w-3.5" />
          )}
          {initial ? "Save" : "Create Template"}
        </Button>
      </div>
    </div>
  );
}

// ─── TemplateRow ─────────────────────────────────────────────────────────────

function TemplateRow({ template, teamId }: { template: ScorecardTemplate; teamId: string }) {
  const [editing, setEditing] = useState(false);
  const deleteMutation = useDeleteScorecardTemplate(teamId);

  if (editing) {
    return <TemplateForm teamId={teamId} initial={template} onClose={() => setEditing(false)} />;
  }

  return (
    <div className="flex items-center gap-3 px-2 py-2 rounded-lg hover:bg-muted/40 transition-colors group">
      <div className="flex-1 min-w-0">
        <p className="text-sm font-medium truncate">{template.name}</p>
        <p className="text-xs text-muted-foreground">
          {template.criteria.length} criterion{template.criteria.length !== 1 ? "a" : ""}
        </p>
      </div>
      <Badge variant="secondary" className="text-[10px] shrink-0">
        {template.criteria.length}
      </Badge>
      <Button
        variant="ghost"
        size="icon"
        className="h-6 w-6 opacity-0 group-hover:opacity-100 transition-opacity shrink-0"
        onClick={() => setEditing(true)}
      >
        <Pencil className="h-3 w-3" />
      </Button>
      <AlertDialog>
        <AlertDialogTrigger asChild>
          <Button
            variant="ghost"
            size="icon"
            className="h-6 w-6 opacity-0 group-hover:opacity-100 transition-opacity text-muted-foreground hover:text-destructive shrink-0"
            disabled={deleteMutation.isPending}
          >
            {deleteMutation.isPending ? (
              <Loader2 className="h-3 w-3 animate-spin" />
            ) : (
              <Trash2 className="h-3 w-3" />
            )}
          </Button>
        </AlertDialogTrigger>
        <AlertDialogContent>
          <AlertDialogHeader>
            <AlertDialogTitle>Delete "{template.name}"?</AlertDialogTitle>
            <AlertDialogDescription>
              This will permanently delete the template and all evaluations submitted using it.
            </AlertDialogDescription>
          </AlertDialogHeader>
          <AlertDialogFooter>
            <AlertDialogCancel>Cancel</AlertDialogCancel>
            <AlertDialogAction
              className="bg-destructive text-destructive-foreground hover:bg-destructive/90"
              onClick={() => deleteMutation.mutate(template.id)}
            >
              Delete
            </AlertDialogAction>
          </AlertDialogFooter>
        </AlertDialogContent>
      </AlertDialog>
    </div>
  );
}

