  useScorecardResponses,
  useSubmitScorecardResponse,
  type Recommendation,
} from "@/hooks/useScorecardResponses";
import { useAuth } from "@/hooks/useAuth";

// ─── Recommendation options ───────────────────────────────────────────────────

const RECOMMENDATIONS: { value: Recommendation; label: string; color: string }[] = [
  { value: "strong_yes", label: "Strong Yes",  color: "text-emerald-600 dark:text-emerald-400" },
  { value: "yes",        label: "Yes",         color: "text-green-600 dark:text-green-400" },
  { value: "neutral",    label: "Neutral",     color: "text-muted-foreground" },
  { value: "no",         label: "No",          color: "text-orange-600 dark:text-orange-400" },
  { value: "strong_no",  label: "Strong No",   color: "text-red-600 dark:text-red-400" },
];

// ─── StarRating ───────────────────────────────────────────────────────────────

function StarRating({
  value,
  max,
  onChange,
  disabled,
}: {
  value: number;
  max: number;
  onChange: (v: number) => void;
  disabled?: boolean;
}) {
  const [hovered, setHovered] = useState<number | null>(null);
  const display = hovered !== null ? hovered : value;

  return (
    <div className="flex items-center gap-0.5">
      {Array.from({ length: max }, (_, i) => i + 1).map((star) => (
        <button
          key={star}
          type="button"
          disabled={disabled}
          onClick={() => onChange(star)}
          onMouseEnter={() => !disabled && setHovered(star)}
          onMouseLeave={() => setHovered(null)}
          className={cn(
            "transition-colors",
            disabled ? "cursor-default" : "cursor-pointer hover:scale-110"
          )}
          aria-label={`Rate ${star} out of ${max}`}
        >
          <Star
            className={cn(
              "h-4 w-4 transition-colors",
              star <= display
                ? "text-amber-400 fill-amber-400"
                : "text-muted-foreground/30"
            )}
          />
        </button>
      ))}
      <span className="text-xs text-muted-foreground ml-1 tabular-nums">
        {value}/{max}
      </span>
    </div>
  );
}

// ─── ScorecardPanel ───────────────────────────────────────────────────────────

interface ScorecardPanelProps {
  resumeId: string;
  jobId: string;
  teamId: string | null | undefined;
}

export default function ScorecardPanel({ resumeId, jobId, teamId }: ScorecardPanelProps) {
  const { user } = useAuth();
  const { data: templates, isLoading: templatesLoading } = useScorecardTemplates(teamId);
  const [selectedTemplateId, setSelectedTemplateId] = useState<string | null>(null);

  // Determine active template
  const activeTemplates = templates ?? [];
  const selectedTemplate = activeTemplates.find((t) => t.id === selectedTemplateId) ?? activeTemplates[0] ?? null;

  // Set default template when list loads
  useEffect(() => {
    if (!selectedTemplateId && activeTemplates.length > 0) {
      setSelectedTemplateId(activeTemplates[0].id);
    }
  }, [activeTemplates, selectedTemplateId]);

  const { data: responses, isLoading: responsesLoading } = useScorecardResponses(resumeId, jobId);
  const submitMutation = useSubmitScorecardResponse();

  // Find existing response for the current evaluator + template
  const myResponse = responses?.find(
    (r) => r.evaluator_id === user?.id && r.template_id === selectedTemplate?.id
  );

  // Local form state
  const [scores, setScores] = useState<Record<string, number>>({});
  const [comment, setComment] = useState("");
  const [recommendation, setRecommendation] = useState<Recommendation>("neutral");

  // Populate form with existing response when it loads
  useEffect(() => {
    if (myResponse) {
      setScores(myResponse.scores ?? {});
      setComment(myResponse.overall_comment ?? "");
      setRecommendation(myResponse.recommendation ?? "neutral");
    } else if (selectedTemplate) {
      // Reset scores to 0 for new template
      const initial: Record<string, number> = {};
      selectedTemplate.criteria.forEach((c) => {
        initial[c.id] = 0;
      });
      setScores(initial);
      setComment("");
      setRecommendation("neutral");
    }
  }, [myResponse, selectedTemplate?.id]);

  async function handleSubmit() {
    if (!selectedTemplate) return;
    await submitMutation.mutateAsync({
      templateId: selectedTemplate.id,
      resumeId,
      jobId,
      scores,
      overallComment: comment.trim() || undefined,
      recommendation,
    });
  }

  const isLoading = templatesLoading || responsesLoading;

  if (!teamId) return null;

  if (isLoading) {
    return (
      <div className="space-y-3">
        <Skeleton className="h-8 w-48" />
        <Skeleton className="h-24 w-full" />
      </div>
    );
  }

  if (activeTemplates.length === 0) {
    return (
      <div className="rounded-lg border border-dashed border-border p-4 text-center">
        <p className="text-xs text-muted-foreground">
          No scorecard templates configured. Ask your team admin to create one.
        </p>
      </div>
    );
  }

  const isAlreadySubmitted = !!myResponse;

  return (
    <div className="space-y-4">
      {/* Template selector */}
      {activeTemplates.length > 1 && (
        <Select
          value={selectedTemplate?.id ?? ""}
          onValueChange={(v) => setSelectedTemplateId(v)}
        >
          <SelectTrigger className="h-8 text-xs w-full max-w-xs">
            <SelectValue placeholder="Select template…" />
          </SelectTrigger>
          <SelectContent>
            {activeTemplates.map((t) => (
              <SelectItem key={t.id} value={t.id} className="text-xs">
                {t.name}
              </SelectItem>
            ))}
          </SelectContent>
        </Select>
      )}

      {selectedTemplate && (
        <>
          <p className="text-xs font-semibold text-muted-foreground uppercase tracking-wider">
            {selectedTemplate.name}
            {isAlreadySubmitted && (
              <span className="ml-2 text-emerald-600 dark:text-emerald-400 normal-case">
                (submitted — you can update)
              </span>
            )}
          </p>

          {/* Criteria */}
          <div className="space-y-3">
            {selectedTemplate.criteria.map((criterion) => (
              <div key={criterion.id} className="space-y-1">
                <div>
                  <Label className="text-xs font-medium">{criterion.label}</Label>
                  {criterion.description && (
                    <p className="text-[11px] text-muted-foreground leading-snug">{criterion.description}</p>
                  )}
                </div>
                <StarRating
                  value={scores[criterion.id] ?? 0}
                  max={criterion.max_score}
                  onChange={(v) => setScores((prev) => ({ ...prev, [criterion.id]: v }))}
                />
              </div>
            ))}
          </div>

          {/* Overall comment */}
          <div className="space-y-1">
            <Label className="text-xs font-medium">Overall Comments</Label>
            <Textarea
              placeholder="Any additional observations about this candidate…"
              value={comment}
              onChange={(e) => setComment(e.target.value)}
              className="text-xs min-h-[72px] resize-none"
              maxLength={1000}
            />
          </div>

          {/* Recommendation */}
          <div className="space-y-1.5">
            <Label className="text-xs font-medium">Recommendation</Label>
            <div className="flex flex-wrap gap-2">
              {RECOMMENDATIONS.map((rec) => (
                <button
                  key={rec.value}
                  type="button"
                  onClick={() => setRecommendation(rec.value)}
                  className={cn(
                    "text-xs px-2.5 py-1 rounded-full border transition-colors font-medium",
                    recommendation === rec.value
                      ? `border-current ${rec.color} bg-current/10`
                      : "border-border text-muted-foreground hover:border-muted-foreground"
                  )}
                >
                  {rec.label}
                </button>
              ))}
            </div>
          </div>

          {/* Submit */}
          <Button
            size="sm"
            className="w-full h-8 text-xs"
            onClick={handleSubmit}
            disabled={submitMutation.isPending}
          >
            {submitMutation.isPending ? (
              <Loader2 className="h-3.5 w-3.5 animate-spin mr-1.5" />
            ) : null}
            {isAlreadySubmitted ? "Update Evaluation" : "Submit Evaluation"}
          </Button>
        </>
      )}
    </div>
  );
}

