      <div className="space-y-2">
        <Skeleton className="h-4 w-32" />
        <Skeleton className="h-16 w-full" />
      </div>
    );
  }

  const allResponses = responses ?? [];
  if (allResponses.length === 0) {
    if (compact) return null;
    return (
      <p className="text-xs text-muted-foreground italic">No evaluations submitted yet.</p>
    );
  }

  // Count recommendations
  const recCounts: Partial<Record<Recommendation, number>> = {};
  allResponses.forEach((r) => {
    recCounts[r.recommendation] = (recCounts[r.recommendation] ?? 0) + 1;
  });

  // Per-criterion average scores across all responses
  // Merge all criteria from all templates referenced
  const criteriaMap: Map<string, { label: string; max_score: number; scores: number[] }> = new Map();

  allResponses.forEach((response) => {
    const template = (templates ?? []).find((t) => t.id === response.template_id);
    if (!template) return;
    template.criteria.forEach((c) => {
      const score = response.scores[c.id];
      if (score === undefined || score === 0) return;
      if (!criteriaMap.has(c.id)) {
        criteriaMap.set(c.id, { label: c.label, max_score: c.max_score, scores: [] });
      }
      criteriaMap.get(c.id)!.scores.push(score);
    });
  });

  const criteriaAverages = Array.from(criteriaMap.entries()).map(([id, info]) => ({
    id,
    label: info.label,
    max_score: info.max_score,
    avg: info.scores.reduce((a, b) => a + b, 0) / info.scores.length,
  }));

  if (compact) {
    return (
      <div className="flex items-center gap-2 flex-wrap">
        <span className="text-[11px] text-muted-foreground font-medium">
          {allResponses.length} eval{allResponses.length !== 1 ? "s" : ""}
        </span>
        {(Object.entries(recCounts) as [Recommendation, number][]).map(([rec, count]) => (
          <span
            key={rec}
            className={cn("text-[10px] px-1.5 py-0.5 rounded-full font-medium", REC_COLOR[rec])}
          >
            {count} {REC_LABEL[rec]}
          </span>
        ))}
      </div>
    );
  }

  return (
    <div className="space-y-4">
      {/* Header */}
      <div className="flex items-center justify-between">
        <p className="text-xs font-semibold text-muted-foreground uppercase tracking-wider">
          Evaluations ({allResponses.length})
        </p>
      </div>

      {/* Recommendation distribution */}
      <div className="flex flex-wrap gap-2">
        {(Object.entries(recCounts) as [Recommendation, number][]).map(([rec, count]) => (
          <span
            key={rec}
            className={cn("text-xs px-2 py-0.5 rounded-full font-medium", REC_COLOR[rec])}
          >
            {count} {REC_LABEL[rec]}
          </span>
        ))}
      </div>

      {/* Per-criterion averages */}
      {criteriaAverages.length > 0 && (
        <div className="space-y-2">
          {criteriaAverages.map((ca) => {
            const pct = Math.round((ca.avg / ca.max_score) * 100);
            return (
              <div key={ca.id} className="space-y-1">
                <div className="flex items-center justify-between">
                  <span className="text-xs text-muted-foreground">{ca.label}</span>
                  <span className="text-xs font-semibold tabular-nums">
                    {ca.avg.toFixed(1)}/{ca.max_score}
                  </span>
                </div>
                <div className="h-1.5 w-full rounded-full bg-muted overflow-hidden">
                  <div
                    className={cn(
                      "h-full rounded-full transition-all",
                      pct >= 70
                        ? "bg-emerald-500"
                        : pct >= 40
                        ? "bg-amber-500"
                        : "bg-red-500"
                    )}
                    style={{ width: `${pct}%` }}
                  />
                </div>
              </div>
            );
          })}
        </div>
      )}
    </div>
  );
}

